  function eachSearch(callback) {
    var containers = document.querySelectorAll('.search');
    for (var i = 0; i < containers.length; i++) {
      var input = containers[i].querySelector('.search-input');
      callback(containers[i], input, input && closers.get(input));
    }
  }

  // Wires up any search box not seen yet and shows every one. Runs on the
  // first load and again whenever Turbo puts a new or morphed page in place,
  // since the page's markup arrives hidden each time.
  function setup() {
    eachSearch(function (container, input) {
      if (!input) return;
      if (!closers.has(input)) wire(container);
      if (closers.has(input)) container.hidden = false;
    });
  }

  document.addEventListener('click', function (event) {
    eachSearch(function (container, _input, close) {
      if (close && !container.contains(event.target)) close();
    });
  });

  // Don't let Turbo cache a page with its suggestions open.
  document.addEventListener('turbo:before-cache', function () {
    eachSearch(function (_container, input, close) {
      if (!close) return;
      input.value = '';
      close();
    });
  });

  ['turbo:load', 'turbo:render', 'turbo:morph', 'turbo:frame-load'].forEach(function (name) {
    document.addEventListener(name, setup);
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setup);
  } else {
    setup();
  }
